```js
world.on('spell:my_spell:failed', ({ actor, reason, range }) => {
  if (nameOfEntity(actor) !== 'You') return;
  if (reason === 'no_target') {
    log('No target in range.', 'system');
  } else if (reason === 'out_of_range') {
